const rtdal001844Source0001 = `print.fontawesome <- function(x, view = interactive(), ...) {

  # nocov start

  dots <- list(...)

  html <-
    paste(
      "<?xml version=\"1.0\" encoding=\"UTF-8\"?>",
      x,
      collapse = "\n"
    )

  htmltools::html_print(
    htmltools::HTML(
      paste(
        c(
          "<!DOCTYPE html>",
          "<html>",
          "<head>",
          "<meta charset=\"utf-8\">",
          "</head>",
          "<body>",
          html,
          "</body>",
          "</html>"
        ),
        collapse = "\n")
    )
  )

  cat(paste0(as.character(x), "\n"))

  # nocov end
}`

