const rtdal001885Source0010 = "as_fs_perms.character <- function(x, ..., mode = 0) {\n  # matches inputs in rwxrwxrwx mode\n  res <- x\n\n  if (!is_windows()) {\n    is_display_mode <- grepl(\"^[rwxXst-]{9}$\", x)\n    res[is_display_mode] <- display_mode_to_symbolic_mode_posix(res[\n      is_display_mode\n    ])\n  } else {\n    is_display_mode <- grepl(\"^[rwxXst-]{3}$\", x)\n    res[is_display_mode] <- display_mode_to_symbolic_mode_windows(res[\n      is_display_mode\n    ])\n  }\n\n  if (length(x) > 1 && length(mode) > 1 && length(x) != length(mode)) {\n    msg <- sprintf(\n      paste0(\n        \"`x` and `mode` must have compatible lengths:\\n\",\n        \"* `x` has length %i\\n\",\n        \"* `mode` has length %i\\n\"\n      ),\n      length(x),\n      length(mode)\n    )\n\n    stop(fs_error(msg))\n  }\n\n  # Recycled over both res and mode\n  n <- max(length(res), length(mode))\n  out <- integer(n)\n  for (i in seq_len(n)) {\n    out[[i]] <- as.integer(\n      .Call(\n        fs_getmode_,\n        res[[((i + 1) %% length(res)) + 1L]],\n        as.integer(mode[[((i + 1) %% length(mode)) + 1L]])\n      )\n    )\n  }\n  new_fs_perms(out)\n}"

const rtdal001885Source0013 = `as_fs_perms.octmode <- function(x, ...) {
  class(x) <- c("fs_perms", "integer")
  x
}`

const rtdal001885Source0014 = `as_fs_perms.numeric <- function(x, ...) {
  if (all(is.na(x) | x == as.integer(x))) {
    x <- as.integer(x)
    return(new_fs_perms(x))
  }
  stop("'x' cannot be coerced to class \"fs_perms\"", call. = FALSE)
}`

