const rtdal001897Source0009 = `collapse <- function(x, sep = "", width = Inf, last = "") {
  if (length(x) == 0) {
    return(character())
  }
  if (any(is.na(x))) {
    return(NA_character_)
  }

  if (nzchar(last) && length(x) > 1) {
    res <- collapse(x[seq(1, length(x) - 1)], sep = sep, width = Inf)
    return(collapse(paste0(res, last, x[length(x)]), width = width))
  }
  x <- paste0(x, collapse = sep)
  if (width < Inf) {
    x_width <- nchar(x, "width", keepNA = FALSE)
    too_wide <- x_width > width
    if (too_wide) {
      x <- paste0(substr(x, 1, width - 3), "...")
    }
  }
  x
}`

const rtdal001897Source0010 = "assert_no_missing <- function(x) {\n  nme <- as.character(substitute(x))\n  idx <- which(is.na(x))\n  if (length(idx) > 0) {\n    number <- prettyNum(length(idx), big.mark = \",\")\n    remaining_width <- getOption(\"width\") - nchar(number, keepNA = FALSE) - 29\n    indexes <- collapse(\n      idx,\n      width = remaining_width,\n      sep = \", \",\n      last = \" and \"\n    )\n    msg <- sprintf(\n      \"`%s` must not have missing values\n  * NAs found at %s locations: %s\",\n      nme,\n      number,\n      indexes\n    )\n\n    stop(fs_error(msg))\n  }\n}"

