const rtdal001915Source0001 = `describe("path", {
  it("returns paths UTF-8 encoded", {
    skip_on_os("solaris")
    expect_equal(Encoding(path("föö")), "UTF-8")
  })

  it("returns paths UTF-8 encoded", {
    skip_on_os("solaris")
    expect_equal(Encoding(path("\U4F60\U597D.R")), "UTF-8")
  })

  it("returns empty strings for empty inputs", {
    expect_equal(path(""), fs_path(""))
    expect_equal(path(character()), fs_path(character()))
    expect_equal(path("foo", character(), "bar"), fs_path(character()))
  })

  it("propagates NA strings", {
    expect_equal(path(NA_character_), fs_path(NA_character_))
    expect_equal(path("foo", NA_character_), fs_path(NA_character_))
    expect_equal(
      path(c("foo", "bar"), c("baz", NA_character_)),
      fs_path(c("foo/baz", NA_character_))
    )
  })

  it("appends a ext if provided", {
    expect_equal(path("foo", ext = "bar"), fs_path("foo.bar"))
    expect_equal(
      path(c("foo", "baz"), ext = "bar"),
      fs_path(c("foo.bar", "baz.bar"))
    )
    expect_equal(
      path(c("foo", "baz", NA_character_), ext = "bar"),
      fs_path(c("foo.bar", "baz.bar", NA_character_))
    )
  })

  it("does not double paths", {
    expect_equal(path("/", "foo"), fs_path("/foo"))
    expect_equal(path("\\", "foo"), fs_path("/foo"))
    expect_equal(path("", "foo"), fs_path("/foo"))
    expect_equal(path("foo/", "bar"), fs_path("foo/bar"))
    expect_equal(path("foo\\", "bar"), fs_path("foo/bar"))
    expect_equal(path("foo//", "bar"), fs_path("foo/bar"))

    # This could be a UNC path, so we keep the doubled path.
    expect_equal(path("//", "foo"), fs_path("//foo"))
  })

  it("errors on paths which are too long", {
    expect_snapshot(
      error = TRUE,
      {
        path(paste(rep("a", 100000), collapse = ""))
        do.call(path, as.list(rep("a", 100000)))
      },
      transform = transform_path_max
    )
  })

  it("follows recycling rules", {
    expect_equal(path("foo", character()), fs_path(character()))
    expect_equal(path("foo", "bar"), fs_path("foo/bar"))
    expect_equal(
      path("foo", c("bar", "baz")),
      fs_path(c("foo/bar", "foo/baz"))
    )
    expect_equal(
      path(c("foo", "qux"), c("bar", "baz")),
      fs_path(c("foo/bar", "qux/baz"))
    )

    expect_error(
      path(c("foo", "qux", "foo2"), c("bar", "baz")),
      "Arguments must have consistent lengths",
      class = "invalid_argument"
    )

    expect_equal(path(ext = character()), fs_path(character()))
    expect_equal(path("foo", ext = character()), fs_path(character()))
    expect_equal(path("foo", ext = "bar"), fs_path("foo.bar"))
    expect_equal(
      path("foo", ext = c("bar", "baz")),
      fs_path(c("foo.bar", "foo.baz"))
    )
    expect_equal(
      path(c("foo", "qux"), ext = c("bar", "baz")),
      fs_path(c("foo.bar", "qux.baz"))
    )

    expect_error(
      path(c("foo", "qux", "foo2"), ext = c("bar", "baz")),
      "Arguments must have consistent lengths",
      class = "invalid_argument"
    )
  })
})`

const rtdal001915Source0002 = `describe("path_wd", {
  it("returns an absolute path from the working directory", {
    x <- path_wd()
    expect_true(is_absolute_path(x))

    expect_equal(x, path(getwd()))
  })
})`

const rtdal001915Source0003 = "describe(\"path_real\", {\n  it(\"returns the real path for symbolic links\", {\n    with_dir_tree(list(\"foo/bar\" = \"test\"), {\n      link_create(path_real(\"foo\"), \"foo2\")\n      expect_equal(path_real(\"foo2\"), path_real(\"foo\"))\n    })\n  })\n\n  it(\"works with indirect symlinks\", {\n    skip_on_os(\"windows\")\n\n    with_dir_tree(\"foo\", {\n      wd <- path_wd()\n      link_create(path(\"..\", path_file(wd)), \"self\")\n      link_create(\"self\", \"link\")\n      expect_equal(path_real(\"link\"), wd)\n    })\n  })\n\n  it(\"works with parent symlinks\", {\n    skip_on_os(\"windows\")\n\n    # If there are symlinks in the parents of relative paths we need to resolve\n    # them.\n    # e.g. working directory is /usr/doc with 'doc' being a symlink to\n    # /usr/share/doc. If we call `path_real(\"a\")` we should return\n    # /usr/share/doc/a.\n    with_dir_tree(\"y\", {\n      wd <- path_wd()\n      link_create(\"y\", \"k\")\n      withr::with_dir(\"k\", {\n        file_create(\"a\")\n        expect_equal(path_real(\"a\"), path(wd, \"/y/a\"))\n        unlink(\"a\")\n      })\n    })\n  })\n\n  it(\"resolves paths before normalizing\", {\n    skip_on_os(\"windows\")\n\n    # if we have the following hierarchy: a/k/y\n    # and a symbolic link 'link-y' pointing to 'y' in directory 'a',\n    # then `path_real(\"link-y/..\")` should return 'k', not 'a'.\n    with_dir_tree(\"a/k/y\", {\n      link_create(\"a/k/y\", \"link-y\")\n\n      expect_equal(path_real(\"link-y/..\"), path_real(\"a/k\"))\n    })\n  })\n\n  it(\"resolves paths before normalizing\", {\n    skip_on_os(\"windows\")\n\n    # if we have the following hierarchy: a/k/y\n    # and a symbolic link 'link-y' pointing to 'y' in directory 'a',\n    # then `path_real(\"link-y/..\")` should return 'k', not 'a'.\n    with_dir_tree(\"k\", {\n      wd <- path_wd()\n      link_create(wd, \"link\")\n\n      withr::with_dir(path_dir(wd), {\n        base <- path_file(wd)\n        expect_equal(path_real(path(base, \"link\")), wd)\n        expect_equal(path_real(path(base, \"link/k\")), path(wd, \"k\"))\n      })\n    })\n  })\n\n  it(\"propagates NAs\", {\n    with_dir_tree(list(\"foo/bar\" = \"test\"), {\n      link_create(path_real(\"foo\"), fs_path(\"foo2\"))\n      expect_equal(path_real(NA_character_), fs_path(NA_character_))\n      expect_equal(\n        path_real(c(\"foo2\", NA_character_)),\n        fs_path(c(path_real(\"foo\"), NA_character_))\n      )\n    })\n  })\n\n  it(\"converts inputs to character if required\", {\n    with_dir_tree(list(\"foo/bar\" = \"test\"), {\n      link_create(path_real(\"foo\"), \"2\")\n      expect_equal(path_real(NA), fs_path(NA_character_)) ## NA (logical) coerced to NA_character_\n      expect_equal(path_real(2), path_real(\"2\"))\n    })\n  })\n})"

const rtdal001915Source0004 = `describe("path_split", {
  it("returns the path split", {
    expect_equal(path_split("foo/bar")[[1]], c("foo", "bar"))
    expect_equal(
      path_split(c("foo/bar", "foo/baz")),
      list(c("foo", "bar"), c("foo", "baz"))
    )
  })

  it("does not split the root path", {
    expect_equal(path_split("/usr/bin")[[1]], c("/", "usr", "bin"))
    expect_equal(path_split("c:/usr/bin")[[1]], c("C:", "usr", "bin"))
    expect_equal(path_split("X:/usr/bin")[[1]], c("X:", "usr", "bin"))
    expect_equal(
      path_split("//server/usr/bin")[[1]],
      c("//server", "usr", "bin")
    )
    expect_equal(
      path_split("\\\\server\\usr\\bin")[[1]],
      c("//server", "usr", "bin")
    )
  })
})`

const rtdal001915Source0005 = `describe("path_tidy", {
  it("does not expand ~", {
    expect_equal(path_tidy("~/foo"), fs_path("~/foo"))
    expect_equal(path_tidy("~/foo/"), fs_path("~/foo"))
    expect_equal(path_tidy("~//foo"), fs_path("~/foo"))
    expect_equal(path_tidy("~//foo"), fs_path("~/foo"))
    expect_equal(path_tidy("~\\foo\\"), fs_path("~/foo"))
  })

  it("always uses / for delimiting, never multiple / or trailing /", {
    expect_equal(path_tidy("foo/bar/baz"), fs_path("foo/bar/baz"))
    expect_equal(path_tidy("foo/bar/baz/"), fs_path("foo/bar/baz"))
    expect_equal(path_tidy("foo//bar//baz"), fs_path("foo/bar/baz"))
    expect_equal(path_tidy("foo//bar//baz//"), fs_path("foo/bar/baz"))
    expect_equal(path_tidy("foo\\bar\\baz"), fs_path("foo/bar/baz"))
    expect_equal(path_tidy("foo\\\\bar\\\\baz"), fs_path("foo/bar/baz"))
    expect_equal(path_tidy("//foo\\\\bar\\\\baz"), fs_path("//foo/bar/baz"))
    expect_equal(path_tidy("foo\\\\bar\\\\baz\\"), fs_path("foo/bar/baz"))
    expect_equal(path_tidy("foo\\\\bar\\\\baz\\\\"), fs_path("foo/bar/baz"))
  })

  it("always capitalizes and appends windows root paths with /", {
    expect_equal(path_tidy("C:"), fs_path("C:/"))
    expect_equal(path_tidy("c:"), fs_path("C:/"))
    expect_equal(path_tidy("X:"), fs_path("X:/"))
    expect_equal(path_tidy("x:"), fs_path("X:/"))
    expect_equal(path_tidy("c:/"), fs_path("C:/"))
    expect_equal(path_tidy("c://"), fs_path("C:/"))
    expect_equal(path_tidy("c:\\"), fs_path("C:/"))
    expect_equal(path_tidy("c:\\\\"), fs_path("C:/"))
  })

  it("passes NA along", {
    expect_equal(path_tidy(NA_character_), fs_path(NA_character_))
    expect_equal(
      path_tidy(c("foo/bar", NA_character_)),
      fs_path(c("foo/bar", NA_character_))
    )
  })

  it("works for non-UTF8 path", {
    x <- "folder//fa\xE7ile.txt/"
    Encoding(x) <- "latin1"
    out <- fs::path_tidy(x)
    expect_equal(Encoding(out), "UTF-8")
    expect_equal(out, fs_path("folder/façile.txt"))
  })

  it("converts inputs to character if required", {
    expect_equal(
      path_tidy(c("foo/bar", NA)),
      fs_path(c("foo/bar", NA_character_))
    )
    expect_equal(path_tidy(1), fs_path("1"))
  })
})`

