const rtdal001918Source0014 = `test_that("filesystems can read, write and delete sanitized files", {
  skip_if_not_utf8()
  skip_on_os("solaris")

  strings <- c(
    # Windows R functions cannot handle the unicode filenames or long filenames + paths correctly.
    if (!is_windows()) {
      readLines(testthat::test_path("blns.txt.xz"), encoding = "UTF-8")
    },
    "the quick brown fox jumped over the lazy dog",
    "résumé",
    "hello\nworld",
    "semi;colon.js",
    ";leading-semi.js",
    "mode_tslash\\.js",
    "slash/.js",
    "col:on.js",
    "star*.js",
    "question?.js",
    "quote\".js",
    "singlequote'.js",
    "brack<e>ts.js",
    "p|pes.js",
    "plus+.js",
    "'five and six<seven'.js",
    " space at front",
    "space at end ",
    ".period",
    "period.",
    "relative/path/to/some/dir",
    "/abs/path/to/some/dir",
    "~/.notssh/authorized_keys",
    "",
    "h?w",
    "h/w",
    "h*w",
    ".",
    "..",
    "./",
    "../",
    "/..",
    "/../",
    "*.|.",
    "./",
    "./foobar",
    "../foobar",
    "../../foobar",
    "./././foobar",
    "|*.what",
    "LPT9.asdf"
  )

  td <- dir_create(file_temp())
  on.exit(dir_delete(td))
  for (str in strings) {
    test_string_fs(str, td)
  }
})`

