	runtime.SetGlobal(ctx, "crpsnorm", runtime.NewNativeFunction(ctx.Global, []runtime.NativeParameter{{Name: "y"}, {Name: "m"}, {Name: "s"}}, func(ctx *runtime.Context, env *runtime.Environment) (runtime.Value, error) {
		runtime.SetLocal(env, "param", runtime.MustCallIn(ctx, env, "na.exclude", runtime.PrimitiveArg(runtime.MustCallIn(ctx, env, "cbind", runtime.PrimitiveArg(runtime.MustLookup(ctx, env, "m")), runtime.PrimitiveArg(runtime.MustLookup(ctx, env, "s")), runtime.PrimitiveArg(runtime.MustLookup(ctx, env, "y"))))))
		runtime.SetLocal(env, "result", runtime.MustCallIn(ctx, env, "-", runtime.PrimitiveArg(runtime.MustCallIn(ctx, env, "f.aux.crpsnorm", runtime.PrimitiveArg(runtime.MustCallIn(ctx, env, "-", runtime.PrimitiveArg(runtime.MustCallIn(ctx, env, "[", runtime.PrimitiveArg(runtime.MustLookup(ctx, env, "param")), runtime.OmittedPrimitiveArg(), runtime.PrimitiveArg(runtime.CharacterScalar("y")))), runtime.PrimitiveArg(runtime.MustCallIn(ctx, env, "[", runtime.PrimitiveArg(runtime.MustLookup(ctx, env, "param")), runtime.OmittedPrimitiveArg(), runtime.PrimitiveArg(runtime.CharacterScalar("m")))))), runtime.PrimitiveArg(runtime.MustCallIn(ctx, env, "[", runtime.PrimitiveArg(runtime.MustLookup(ctx, env, "param")), runtime.OmittedPrimitiveArg(), runtime.PrimitiveArg(runtime.CharacterScalar("s")))))), runtime.PrimitiveArg(runtime.MustCallIn(ctx, env, "*", runtime.PrimitiveArg(runtime.NumericVector(0.5)), runtime.PrimitiveArg(runtime.MustCallIn(ctx, env, "f.aux.crpsnorm", runtime.PrimitiveArg(runtime.NumericVector(0.)), runtime.PrimitiveArg(runtime.MustCallIn(ctx, env, "*", runtime.PrimitiveArg(runtime.MustCallIn(ctx, env, "sqrt", runtime.PrimitiveArg(runtime.NumericVector(2.)))), runtime.PrimitiveArg(runtime.MustCallIn(ctx, env, "[", runtime.PrimitiveArg(runtime.MustLookup(ctx, env, "param")), runtime.OmittedPrimitiveArg(), runtime.PrimitiveArg(runtime.CharacterScalar("s"))))))))))))
		return runtime.MustCallIn(ctx, env, "napredict", runtime.PrimitiveArg(runtime.MustCallIn(ctx, env, "attr", runtime.PrimitiveArg(runtime.MustLookup(ctx, env, "param")), runtime.PrimitiveArg(runtime.CharacterScalar("na.action")))), runtime.PrimitiveArg(runtime.MustLookup(ctx, env, "result"))), nil
	}))

	// r2go: matrix-lowered block 7/7; original R follows.
	// R| check.newdata <- function(newdata){
	// R|
	// R|   ## function checks whether newdata is a valid object to be passed to
	// R|   ## predict.georob or lgnpp
