const rtdal002041Source0022 = `add1.georob <- function( object, scope, scale = 0, test=c("none", "Chisq"),
  k = 2, trace = FALSE, fixed = TRUE, use.fitted.param = TRUE, verbose = 0,
  ncores = 1, ... )
{

  ## add1 method for class georob based on add1.default{stats}

  ## 2014-03-12 AP
  ## 2014-04-24 AP function returns only variogram parameters of best fitted object
  ## 2014-05-15 AP changes for version 3 of RandomFields
  ## 2015-07-23 AP warning and action for attempt to process Gaussian REML object
  ## 2015-07-23 AP changes for dropping terms from model with fixed variogram parameters
  ## 2015-08-28 AP computation of hessian suppressed
  ## 2016-05-22 AP changes for better computational efficiency
  ## 2016-05-27 AP diagnostics about convergence
  ## 2016-07-20 AP changes for parallel computations
  ## 2016-08-09 AP changes for nested variogram models
  ## 2018-01-05 AP improved memory management in parallel computations
  ##               improved error handling during parallel computations
  ## 2018-08-27 AP elimination of data argument
  ## 2020-02-14 AP sanity checks of arguments and for if() and switch()
  ## 2023-01-27 AP extracting data from object and using data in update
  ## 2023-12-20 AP added on.exit(options(old.opt)), replaced makeCluster by makePSOCKcluster
  ## 2023-12-21 AP replacement of identical(class(...), ...) by inherits(..., ...)
  ## 2024-02-01 AP saving SOCKcluster.RData to tempdir()
  ## 2024-02-21 AP conditionally prevent recursive parallelizations in pmm or f.aux.gcr

#
  ## match arguments

  test <- match.arg(test)

  ## check arguments

  stopifnot(identical(length(trace), 1L)            && is.logical(trace))
  stopifnot(identical(length(fixed), 1L)            && is.logical(fixed))
  stopifnot(identical(length(use.fitted.param), 1L) && is.logical(use.fitted.param))

  stopifnot(identical(length(k), 1L)       && is.numeric(k)       && k > 0)
  stopifnot(identical(length(verbose), 1L) && is.numeric(verbose) && verbose >= 0)
  stopifnot(identical(length(ncores), 1L)  && is.numeric(ncores)  && ncores >= 1)


  ## auxiliary function for fitting model and extracting aic by add1 and drop1

  f.aux.add1.drop1 <- function( tt, change, scale, trace, ... ){

    ## objects object, k, n0, verbose are taken from parent environment

    if(trace > 1.) {
      cat( paste( "\ntrying ", change, sep="" ), tt, "\n", sep = "")
      utils::flush.console()
    }

    nfit <- update(
      object, as.formula(paste("~ .", change, tt)), data = data,
      verbose = verbose, object. = object
    )

    converged <- TRUE

    if( !is.na(!nfit[["converged"]]) && !nfit[["converged"]] ){
      converged <- FALSE
      warning( "there were errors: call function with argument 'verbose' > 1" )
      if( verbose > 0. ) cat(
        "lack of convergence when fitting model", paste("~ .", change, tt),
        "\nconvergence code:", nfit$convergence.code, "\n"
      )
    }

    nnew <- nobs( nfit, use.fallback = TRUE )
    if( all(is.finite(c(n0, nnew))) && nnew != n0 ) stop(
      "number of rows in use has changed: remove missing values?"
    )
    df.aic <-  c( extractAIC( nfit, scale, k = k, REML = FALSE, ... ), as.numeric(converged))
    names( df.aic ) <- c("df", "AIC", "converged")
    #   attr( df.aic, "nfit" ) <- list(
    #     variogram.object = nfit[["variogram.object"]],
    #     initial.objects = nfit[["initial.objects"]],
    #     call = nfit[["call"]]
    #   )
    df.aic
  }

  ## evaluate terms and scope

  if( missing(scope ) || is.null( scope ) ) stop("no terms in scope")
  if( !is.character( scope ) ) scope <- add.scope( object, update.formula(object, scope) )
  if( !length(scope)) stop( "no terms in scope for adding to object" )

  ## manipulate call

  cl <- object[["call"]]

  ## set verbose

  cl <- f.call.set_x_to_value( cl, "verbose", verbose )

  ## update object call to avoid computation of hessian

  cl <- f.call.set_x_to_value_in_fun( cl, "control", "control.georob", "hessian", FALSE )

  ## update object call to avoid computation of covariance matrices

  cl <- f.call.set_x_to_value_in_fun( cl, "control", "control.georob", "cov.bhat", FALSE )
  #   cl <- f.call.set_x_to_value_in_fun( cl, "control", "control.georob", "cov.betahat", FALSE )
  cl <- f.call.set_x_to_value_in_fun( cl, "control", "control.georob", "cov.delta.bhat", FALSE )
  cl <- f.call.set_x_to_value_in_fun( cl, "control", "control.georob", "cov.delta.bhat.betahat", FALSE )
  cl <- f.call.set_x_to_value_in_fun( cl, "control", "control.georob", "cov.ehat", FALSE )
  cl <- f.call.set_x_to_value_in_fun( cl, "control", "control.georob", "cov.ehat.p.bhat", FALSE )

  ## conditionally prevent recursive parallelizations in pmm or f.aux.gcr

  if( ncores > 1L && !object[["control"]][["pcmp"]][["allow.recursive"]] ){
    cl <- f.call.prevent_recursive_parallelization( cl )
  }

  ## update call in object

  object[["call"]] <- cl

  ## check if object is result of GAUSSIAN ML fit, manipulate its call and
  ## re-fit it by ML if required

  if(
    object[["tuning.psi"]] >= object[["control"]][["tuning.psi.nr"]] &&
    identical( object[["control"]][["ml.method"]], "REML" )
  ){
    warning( "'object' was estmated by Gaussian REML which cannot be used for ",
      "adding/dropping single terms\n=> 'object' is re-fitted by Gaussian ML ",
      "before adding/deleting terms"
    )

    cl <- object[["call"]]

    cl <- f.call.set_x_to_value_in_fun( cl, "control", "control.georob", "ml.method", "ML" )

    object[["call"]] <- cl
    object <- update( object )

  }

  ## manipulate object call if variogram parameters are fixed or estimation
  ## should start from estimated values in object

  if( fixed || use.fitted.param ){

    cl <- f.call.set_allxxx_to_fitted_values( object )

    if( fixed ) cl <- f.call.set_allfitxxx_to_false( cl )

    object[["call"]] <- cl

    object <- update( object )

  }



  ##  check whether argument "data" has been provided in call and get data
  ##  from parent.frame

  extras <- match.call( expand.dots = FALSE )$...
  data <- extras[names(extras) %in% "data"]
  if(
    length( data ) &&
    exists( as.character( data ), envir = parent.frame() ) #&&
    #     !control[["initial.param"]]
  ){
    data <- eval( data[[1L]], parent.frame() )

  } else {

    ## get data.frame with required variables (note that the data.frame passed
    ## as data argument to georob must exist in GlobalEnv)

    data <- get( as.list( cl )[["data"]], parent.frame() )

  }

  if( inherits( object[["na.action"]], "omit" ) ) data <- na.omit(data)

  ## initialize result

  ns <- length( scope )
  ans <- matrix(
    nrow = ns + 1L, ncol = 3L,
    dimnames = list(c("<none>", scope), c("df", "AIC", "converged"))
  )
  ans[1L,  ] <- c(
    extractAIC( object, scale, k = k, REML = FALSE, ... ),
    object[["converged"]]
  )

  ## loop over all components of scope

  n0 <- nobs( object, use.fallback = TRUE )
  env <- environment( formula(object) )

  ## prepare for parallel execution

  if( ncores > 1L ){
    ncores <- min( ncores, ns, parallel::detectCores() )
    trace <- 0
    verbose <- 0.
  }

  ## set default value for control of forking if missing (required for backward compatibility)

  if( is.null( object[["control"]][["pcmp"]][["fork"]] ) ){
    object[["control"]][["pcmp"]][["fork"]] <- !identical( .Platform[["OS.type"]], "windows" )
  }

  if( ncores > 1L && !object[["control"]][["pcmp"]][["fork"]] ){

    ## create a PSOCK cluster on windows OS

    fname <- file.path( tempdir(), "SOCKcluster.RData" )

    clstr <- makePSOCKcluster( ncores )
    save( clstr, file = fname )
    old.opt <- options( error = f.stop.cluster )
    on.exit( options( old.opt ) )

    ## export required items to workers

    junk <- clusterEvalQ( clstr, require( georob, quietly = TRUE ) )
    junk <- clusterExport(
      clstr,
      c( "object", "data", "k", "n0", "verbose" ), envir =  environment()
    )

    result <- parLapply(
      clstr,
      scope,
      f.aux.add1.drop1,
      change = "+", scale = scale, trace = trace,
      ...
    )

    f.stop.cluster( clstr, fname )

  } else {

    ## fork child processes on non-windows OS

    result <- mclapply(
      scope, f.aux.add1.drop1,
      change = "+", scale = scale, trace = trace,
      mc.cores = ncores,
      mc.allow.recursive = object[["control"]][["pcmp"]][["allow.recursive"]],
      ...
    )

  }

  #   fits <- list(
  #     list(
  #       variogram.object = object[["variogram.object"]],
  #       initial.objects = object[["initial.objects"]],
  #       call = object[["call"]]
  #     )
  #   )
  #   fits[2:NROW(ans)] <- lapply( result, function(x) attr( x, "nfit" ) )
  result <- t( simplify2array( result ) )
  ans[2L:NROW(ans), ] <- result
  if(!all( as.logical(result[, "converged"]) ) ) warning(
    "lack of convergence when fitting models"
  )

  ## store results

  dfs <- ans[, 1L] - ans[1L, 1L]
  dfs[1L] <- NA
  aod <- data.frame( Df = dfs, AIC = ans[, 2L], Converged = as.logical( ans[, 3L] ) )

  ## likelihood ratio test

  if(test == "Chisq") {
    dev <- ans[, 2L] - k*ans[, 1L]
    dev <- dev[1L] - dev; dev[1L] <- NA
    nas <- !is.na(dev)
    P <- dev
    P[nas] <- safe_pchisq(dev[nas], dfs[nas], lower.tail=FALSE)
    aod[, c("LRT", "Pr(>Chi)")] <- list(dev, P)
    aod <- aod[, c( "Df", "AIC", "LRT", "Pr(>Chi)", "Converged" )]
  }

  ## format results

  head <- c(
    "Single term additions", "\nModel:", deparse(formula(object)),
    if(scale > 0.) paste("\nscale: ", format(scale), "\n")
  )
  class(aod) <- c("anova", "data.frame")
  attr( aod, "heading") <- head
  #   attr( aod, "nfit" ) <- fits[[which.min( aod[, "AIC"])]]

  aod

}`

const rtdal002041Source0023 = `drop1.georob <- function( object, scope, scale = 0, test=c( "none", "Chisq" ),
  k = 2, trace = FALSE, fixed = TRUE, use.fitted.param = TRUE, verbose = 0,
  ncores = 1, ... )
{

  ## drop1 method for class georob based on drop1.default{stats}

  ## 2014-03-12 AP
  ## 2014-04-24 AP function returns only variogram parameters of best fitted object
  ## 2014-05-15 AP changes for version 3 of RandomFields
  ## 2015-07-23 AP warning and action for attempt to process Gaussian REML object
  ## 2015-07-23 AP changes for dropping terms from model with fixed variogram parameters
  ## 2015-08-28 AP computation of hessian suppressed
  ## 2016-05-22 AP changes for better computational efficiency
  ## 2016-05-27 AP diagnostics about convergence
  ## 2016-07-20 AP changes for parallel computations
  ## 2016-08-09 AP changes for nested variogram models
  ## 2018-01-05 AP improved memory management in parallel computations
  ##               improved error handling during parallel computations
  ## 2018-08-27 AP elimination of data argument
  ## 2020-02-14 AP sanity checks of arguments and for if() and switch()
  ## 2023-01-27 AP extracting data from object and using data in update
  ## 2023-12-20 AP added on.exit(options(old.opt)), replaced makeCluster by makePSOCKcluster
  ## 2023-12-21 AP replacement of identical(class(...), ...) by inherits(..., ...)
  ## 2024-02-01 AP saving SOCKcluster.RData to tempdir()
  ## 2024-02-21 AP conditionally prevent recursive parallelizations in pmm or f.aux.gcr

  ## match arguments

  test <- match.arg(test)

  ## check arguments

  stopifnot(identical(length(trace), 1L)            && is.logical(trace))
  stopifnot(identical(length(fixed), 1L)            && is.logical(fixed))
  stopifnot(identical(length(use.fitted.param), 1L) && is.logical(use.fitted.param))

  stopifnot(identical(length(k), 1L)       && is.numeric(k)       && k > 0)
  stopifnot(identical(length(verbose), 1L) && is.numeric(verbose) && verbose >= 0)
  stopifnot(identical(length(ncores), 1L)  && is.numeric(ncores)  && ncores >= 1)

  ## auxiliary function for fitting model and extracting aic by add1 and drop1

  f.aux.add1.drop1 <- function( tt, change, scale, trace, ... ){

    ## objects object, k, n0, verbose are taken from parent environment

    if(trace > 1.) {
      cat( paste( "\ntrying ", change, sep="" ), tt, "\n", sep = "")
      utils::flush.console()
    }

    nfit <- update(
      object, as.formula(paste("~ .", change, tt)), data = data,
      verbose = verbose, object. = object
    )

    converged <- TRUE

    if( !is.na(!nfit[["converged"]]) && !nfit[["converged"]] ){
      converged <- FALSE
      warning( "there were errors: call function with argument 'verbose' > 1" )
      if( verbose > 0. ) cat(
        "lack of convergence when fitting model", paste("~ .", change, tt),
        "\nconvergence code:", nfit$convergence.code, "\n"
      )
    }

    nnew <- nobs( nfit, use.fallback = TRUE )
    if( all(is.finite(c(n0, nnew))) && nnew != n0 ) stop(
      "number of rows in use has changed: remove missing values?"
    )
    df.aic <-  c( extractAIC( nfit, scale, k = k, REML = FALSE, ... ), as.numeric(converged))
    names( df.aic ) <- c("df", "AIC", "converged")
    #   attr( df.aic, "nfit" ) <- list(
    #     variogram.object = nfit[["variogram.object"]],
    #     initial.objects = nfit[["initial.objects"]],
    #     call = nfit[["call"]]
    #   )
    df.aic
  }

  ## manipulate call

  cl <- object[["call"]]

  ## set verbose

  cl <- f.call.set_x_to_value( cl, "verbose", verbose )

  ## update object call to avoid computation of hessian

  cl <- f.call.set_x_to_value_in_fun( cl, "control", "control.georob", "hessian", FALSE )

  ## update object call to avoid computation of covariance matrices

  cl <- f.call.set_x_to_value_in_fun( cl, "control", "control.georob", "cov.bhat", FALSE )
  #   cl <- f.call.set_x_to_value_in_fun( cl, "control", "control.georob", "cov.betahat", FALSE )
  cl <- f.call.set_x_to_value_in_fun( cl, "control", "control.georob", "cov.delta.bhat", FALSE )
  cl <- f.call.set_x_to_value_in_fun( cl, "control", "control.georob", "cov.delta.bhat.betahat", FALSE )
  cl <- f.call.set_x_to_value_in_fun( cl, "control", "control.georob", "cov.ehat", FALSE )
  cl <- f.call.set_x_to_value_in_fun( cl, "control", "control.georob", "cov.ehat.p.bhat", FALSE )

  ## conditionally prevent recursive parallelizations in pmm or f.aux.gcr

  if( ncores > 1L && !object[["control"]][["pcmp"]][["allow.recursive"]] ){
    cl <- f.call.prevent_recursive_parallelization( cl )
  }

  ## update call in object

  object[["call"]] <- cl

  ## check if object is result of GAUSSIAN ML fit, manipulate its call and
  ## re-fit it by ML if required

  if(
    object[["tuning.psi"]] >= object[["control"]][["tuning.psi.nr"]] &&
    identical( object[["control"]][["ml.method"]], "REML" )
  ){
    warning( "'object' was estmated by Gaussian REML which cannot be used for ",
      "adding/dropping single terms\n=> 'object' is re-fitted by Gaussian ML ",
      "before adding/deleting terms"
    )

    cl <- object[["call"]]

    cl <- f.call.set_x_to_value_in_fun( cl, "control", "control.georob", "ml.method", "ML" )

    object[["call"]] <- cl
    object <- update( object )

  }

  ## manipulate object call if variogram parameters are fixed or estimation
  ## should start from estimated values in object

  if( fixed || use.fitted.param ){

    cl <- f.call.set_allxxx_to_fitted_values( object )

    if( fixed ) cl <- f.call.set_allfitxxx_to_false( cl )

    object[["call"]] <- cl

    object <- update( object )

  }

  ## evaluate terms and scope

  tl <- attr( terms(object), "term.labels" )
  if( missing(scope) ) {
    scope <- drop.scope( object )
  } else {
    if( !is.character(scope) ) scope <- attr(
      terms(update.formula(object, scope)), "term.labels"
    )
    if( !all( match(scope, tl, 0L) > 0L) ) stop("scope is not a subset of term labels")
  }

  ##  check whether argument "data" has been provided in call and get data
  ##  from parent.frame

  extras <- match.call( expand.dots = FALSE )$...
  data <- extras[names(extras) %in% "data"]
  if(
    length( data ) &&
    exists( as.character( data ), envir = parent.frame() ) #&&
    #     !control[["initial.param"]]
  ){
    data <- eval( data[[1L]], parent.frame() )

  } else {

    ## get data.frame with required variables (note that the data.frame passed
    ## as data argument to georob must exist in GlobalEnv)

    data <- get( as.list( cl )[["data"]], parent.frame() )

  }

  if( inherits( object[["na.action"]], "omit" ) ) data <- na.omit(data)

  ## initialize result

  ns <- length( scope )
  ans <- matrix(
    nrow = ns + 1L, ncol = 3L,
    dimnames = list(c("<none>", scope), c("df", "AIC", "converged"))
  )
  ans[1L,  ] <- c(
    extractAIC( object, scale, k = k, REML = FALSE, ... ),
    object[["converged"]]
  )

  ## loop over all components of scope

  n0 <- nobs( object, use.fallback = TRUE )
  env <- environment( formula(object) )

  ## prepare for parallel execution

  if( ncores > 1L ){
    ncores <- min( ncores, ns, parallel::detectCores() )
    trace <- 0
    verbose <- 0.
  }

  ## set default value for control of forking if missing (required for backward compatibility)

  if( is.null( object[["control"]][["pcmp"]][["fork"]] ) ){
    object[["control"]][["pcmp"]][["fork"]] <- !identical( .Platform[["OS.type"]], "windows" )
  }

  if( ncores > 1L && !object[["control"]][["pcmp"]][["fork"]] ){

    ## create a PSOCK cluster on windows OS

    fname <- file.path( tempdir(), "SOCKcluster.RData" )

    clstr <- makePSOCKcluster( ncores )
    save( clstr, file = fname )
    old.opt <- options( error = f.stop.cluster )
    on.exit( options( old.opt ) )

    ## export required items to workers

    junk <- clusterEvalQ( clstr, require( georob, quietly = TRUE ) )
    junk <- clusterExport(
      clstr, c( "object", "data", "k", "n0", "verbose" ), envir =  environment()
    )

    result <- parLapply(
      clstr,
      scope,
      f.aux.add1.drop1,
      change = "-", scale = scale, trace = trace,
      ...
    )

    f.stop.cluster( clstr, fname )

  } else {

    ## fork child processes on non-windows OS

    result <- mclapply(
      scope, f.aux.add1.drop1,
      change = "-", scale = scale, trace = trace,
      mc.cores = ncores,
      mc.allow.recursive = object[["control"]][["pcmp"]][["allow.recursive"]],
      ...
    )

  }

  #   fits <- list(
  #     list(
  #       variogram.object = object[["variogram.object"]],
  #       initial.objects = object[["initial.objects"]],
  #       call = object[["call"]]
  #     )
  #   )
  #   fits[2:NROW(ans)] <- lapply( result, function(x) attr( x, "nfit" ) )
  result <- t( simplify2array( result ) )
  ans[2L:NROW(ans), ] <- result
  if(!all( as.logical(result[, "converged"]) ) ) warning(
    "lack of convergence when fitting models"
  )

  ## store results

  dfs <- ans[1L , 1L] - ans[, 1L]
  dfs[1L] <- NA
  aod <- data.frame( Df = dfs, AIC = ans[, 2L], Converged = as.logical( ans[, 3L] ) )

  ## likelihood ratio test

  if(test == "Chisq") {
    dev <- ans[, 2L] - k*ans[, 1L]
    dev <- dev - dev[1L] ; dev[1L] <- NA
    nas <- !is.na(dev)
    P <- dev
    P[nas] <- safe_pchisq(dev[nas], dfs[nas], lower.tail = FALSE)
    aod[, c("LRT", "Pr(>Chi)")] <- list(dev, P)
    aod <- aod[, c( "Df", "AIC", "LRT", "Pr(>Chi)", "Converged" )]
  }

  ## format results

  head <- c(
    "Single term deletions", "\nModel:", deparse(formula(object)),
    if(scale > 0.) paste("\nscale: ", format(scale), "\n"))
  class(aod) <- c("anova", "data.frame")
  attr( aod, "heading") <- head
  #   attr( aod, "nfit" ) <- fits[[which.min( aod[, "AIC"])]]

  aod

}`

const rtdal002041Source0024 = `step <- function( object, ... ) UseMethod( "step" )`

const rtdal002041Source0026 = "step.georob <- function( object, scope, scale = 0,\n  direction = c( \"both\", \"backward\", \"forward\" ), trace = 1, keep = NULL, steps = 1000,\n  k = 2, fixed.add1.drop1 = TRUE, fixed.step = fixed.add1.drop1,\n  use.fitted.param = TRUE, verbose = 0, ncores = 1, ... )\n{\n\n  ## step method for class georob\n\n  ## 2014-06-05 AP\n  ## 2015-07-23 AP warning and action for attempt to process Gaussian REML object\n  ## 2015-07-23 AP changes for dropping terms from model with fixed variogram parameters\n  ## 2016-05-22 AP correction of error when variogram parameters are fixed\n  ## 2016-05-22 AP changes for better computational efficiency\n  ## 2016-07-20 AP changes for parallel computations\n  ## 2016-08-09 AP changes for nested variogram models\n  ## 2018-01-05 AP improved memory management in parallel computations\n  ## 2018-08-27 AP elimination of data argument\n  ## 2020-02-14 AP sanity checks of arguments and for if() and switch()\n  ## 2023-01-27 AP extracting data from object and using data in update\n  ## 2023-12-21 AP replacement of identical(class(...), ...) by inherits(..., ...)\n\n  ## match arguments\n\n  direction <- match.arg(direction)\n\n  ## check arguments\n\n  stopifnot(identical(length(use.fitted.param), 1L) && is.logical(use.fitted.param))\n  stopifnot(identical(length(fixed.add1.drop1), 1L) && is.logical(fixed.add1.drop1))\n  stopifnot(identical(length(fixed.step), 1L)       && is.logical(fixed.step))\n\n  stopifnot(identical(length(trace), 1L)   && is.numeric(trace)   && trace >= 0)\n  stopifnot(identical(length(k), 1L)       && is.numeric(k)       && k > 0)\n  stopifnot(identical(length(verbose), 1L) && is.numeric(verbose) && verbose >= 0)\n  stopifnot(identical(length(ncores), 1L)  && is.numeric(ncores)  && ncores >= 1)\n  stopifnot(identical(length(steps), 1L)   && is.numeric(steps)   && steps > 0)\n\n  ## code of step{stats} complemented by argument fixed to control whether\n  ## variogram parameters should be kept fixed\n\n  ## auxiliary functions\n\n  mydeviance <- function(x, ...){\n    dev <- deviance(x, REML = FALSE, ...)\n    if(!is.null(dev)) dev else extractAIC(x, k=0., REML = FALSE, ...)[2L]\n  }\n\n  cut.string <- function(string){\n    if(length(string) > 1L)\n    string[-1L] <- paste0(\"\\n\", string[-1L])\n    string\n  }\n\n  re.arrange <- function(keep){\n    namr <- names(k1 <- keep[[1L]])\n    namc <- names(keep)\n    nc <- length(keep)\n    nr <- length(k1)\n    array(unlist(keep, recursive = FALSE), c(nr, nc), list(namr, namc))\n  }\n\n  step.results <- function(models, fit, object, usingCp=FALSE){\n    change <- sapply(models, \"[[\", \"change\")\n    rd <- sapply(models, \"[[\", \"deviance\")\n    dd <- c(NA, abs(diff(rd)))\n    rdf <- sapply(models, \"[[\", \"df.resid\")\n    ddf <- c(NA, diff(rdf))\n    AIC <- sapply(models, \"[[\", \"AIC\")\n    heading <- c(\"Stepwise Model Path \\nAnalysis of Deviance Table\",\n      \"\\nInitial Model:\", deparse(formula(object)),\n      \"\\nFinal Model:\", deparse(formula(fit)),\n      \"\\n\")\n    aod <- data.frame(Step = I(change), Df = ddf, Deviance = dd,\n      \"Resid. Df\" = rdf, \"Resid. Dev\" = rd, AIC = AIC,\n      check.names = FALSE)\n    if(usingCp) {\n      cn <- colnames(aod)\n      cn[cn == \"AIC\"] <- \"Cp\"\n      colnames(aod) <- cn\n    }\n    attr(aod, \"heading\") <- heading\n    ##stop gap attr(aod, \"class\") <- c(\"anova\", \"data.frame\")\n    fit$anova <- aod\n    fit\n  }\n\n  ## evaluate terms and scope\n\n  Terms <- terms(object)\n  object$call$formula <- object$formula <- Terms\n  md <- missing(direction)\n  backward <- direction == \"both\" | direction == \"backward\"\n  forward  <- direction == \"both\" | direction == \"forward\"\n  if(missing(scope)) {\n    fdrop <- numeric()\n    fadd <- attr(Terms, \"factors\")\n    if(md) forward <- FALSE\n  }\n  else {\n    if(is.list(scope)) {\n      fdrop <- if(!is.null(fdrop <- scope$lower))\n      attr(terms(update.formula(object, fdrop)), \"factors\")\n      else numeric()\n      fadd <- if(!is.null(fadd <- scope$upper))\n      attr(terms(update.formula(object, fadd)), \"factors\")\n    }\n    else {\n      fadd <- if(!is.null(fadd <- scope))\n      attr(terms(update.formula(object, scope)), \"factors\")\n      fdrop <- numeric()\n    }\n  }\n  models <- vector(\"list\", steps)\n  if(!is.null(keep)) keep.list <- vector(\"list\", steps)\n  n <- nobs(object, use.fallback = TRUE)  # might be NA\n\n  ## store number of fitted variogram parameters\n\n  n.fitted.param.aniso <- sum(\n    unlist(\n      lapply(\n        object[[\"variogram.object\"]],\n        function(x) c( x[[\"fit.param\"]], x[[\"fit.aniso\"]] )\n      )))\n\n\n  ## check consistency of arguments\n\n  if( !fixed.add1.drop1 && fixed.step ){\n    cat( \"\\n'fixed.step' set equal to FALSE because fixed.add1.drop1 == FALSE\\n\\n\" )\n    fixed.step <- FALSE\n  }\n\n  cl <- object[[\"call\"]]\n\n  ## set verbose\n\n  cl <- f.call.set_x_to_value( cl, \"verbose\", verbose )\n\n  ## update object call to avoid computation of hessian\n\n  cl <- f.call.set_x_to_value_in_fun( cl, \"control\", \"control.georob\", \"hessian\", FALSE )\n\n  ## update object call to avoid computation of covariance matrices\n\n  cl <- f.call.set_x_to_value_in_fun( cl, \"control\", \"control.georob\", \"cov.bhat\", FALSE )\n  #   cl <- f.call.set_x_to_value_in_fun( cl, \"control\", \"control.georob\", \"cov.betahat\", FALSE )\n  cl <- f.call.set_x_to_value_in_fun( cl, \"control\", \"control.georob\", \"cov.delta.bhat\", FALSE )\n  cl <- f.call.set_x_to_value_in_fun( cl, \"control\", \"control.georob\", \"cov.delta.bhat.betahat\", FALSE )\n  cl <- f.call.set_x_to_value_in_fun( cl, \"control\", \"control.georob\", \"cov.ehat\", FALSE )\n  cl <- f.call.set_x_to_value_in_fun( cl, \"control\", \"control.georob\", \"cov.ehat.p.bhat\", FALSE )\n\n  object[[\"call\"]] <- cl\n\n  ## check if object is result of GAUSSIAN ML fit and manipulate its call to\n  ## refit it by ML if required\n\n  if(\n    object[[\"tuning.psi\"]] >= object[[\"control\"]][[\"tuning.psi.nr\"]] &&\n    identical( object[[\"control\"]][[\"ml.method\"]], \"REML\" )\n  ){\n    warning( \"'object' was estmated by Gaussian REML which cannot be used for \",\n      \"adding/dropping single terms\\n=> 'object' is re-fitted by Gaussian ML \",\n      \"before adding/deleting terms\"\n    )\n\n    cl <- object[[\"call\"]]\n\n    cl <- f.call.set_x_to_value_in_fun( cl, \"control\", \"control.georob\", \"ml.method\", \"ML\" )\n\n    object[[\"call\"]] <- cl\n    object <- update( object )\n\n  }\n\n  ## manipulate object call if variogram parameters are fixed or estimation\n  ## should start from estimated values in object\n\n  if( fixed.step || use.fitted.param ){\n\n    cl <- f.call.set_allxxx_to_fitted_values( object )\n\n    if( fixed.step ) cl <- f.call.set_allfitxxx_to_false( cl )\n\n    object[[\"call\"]] <- cl\n\n    object <- update( object )\n\n  }\n\n  ##  check whether argument \"data\" has been provided in call and get data\n  ##  from parent.frame\n\n  extras <- match.call( expand.dots = FALSE )$...\n  data <- extras[names(extras) %in% \"data\"]\n  if(\n    length( data ) &&\n    exists( as.character( data ), envir = parent.frame() ) #&&\n    #     !control[[\"initial.param\"]]\n  ){\n    data <- eval( data[[1L]], parent.frame() )\n\n  } else {\n\n    ## get data.frame with required variables (note that the data.frame passed\n    ## as data argument to georob must exist in GlobalEnv)\n\n    data <- get( as.list( cl )[[\"data\"]], parent.frame() )\n\n  }\n\n  if( inherits( object[[\"na.action\"]], \"omit\" ) ) data <- na.omit(data)\n\n  ## now start the model search\n\n  fit <- object\n\n  bAIC <- extractAIC(fit, scale, k = k, REML = FALSE, ...)\n  edf <- bAIC[1L]\n  bAIC <- bAIC[2L]\n  if( fixed.add1.drop1 && !fixed.step ) bAIC <- bAIC - k * n.fitted.param.aniso\n  if(is.na(bAIC)) stop(\"AIC is not defined for this model, so 'step' cannot proceed\")\n  if(bAIC == -Inf) stop(\"AIC is -infinity for this model, so 'step' cannot proceed\")\n  nm <- 1L\n  ## Terms <- fit$terms\n  if(trace) {\n    cat(\"Start:  AIC=\", format(round(bAIC, 2)), \"\\n\",\n      cut.string(deparse(formula(fit))), \"\\n\\n\", sep = \"\")\n    utils::flush.console()\n  }\n\n  ## FIXME think about df.residual() here\n  models[[nm]] <- list(deviance = mydeviance(fit, ...), df.resid = n - edf,\n    change = \"\", AIC = bAIC)\n  if(!is.null(keep)) keep.list[[nm]] <- keep(fit, bAIC)\n  usingCp <- FALSE\n\n  while(steps > 0L) {\n    steps <- steps - 1L\n    AIC <- bAIC\n    ffac <- attr(Terms, \"factors\")\n    scope <- factor.scope(ffac, list(add = fadd, drop = fdrop))\n    aod <- NULL\n    change <- NULL\n    if(backward && length(scope$drop)) {\n      aod <- drop1(\n        fit, scope$drop, scale = scale,\n        k = k, trace = trace >= 1, fixed = fixed.add1.drop1,\n        use.fitted.param = use.fitted.param, verbose = verbose,\n        ncores = ncores, data = data, ...\n      )\n      rn <- row.names(aod)\n      row.names(aod) <- c(rn[1L], paste(\"-\", rn[-1L], sep=\" \"))\n      ## drop zero df terms first: one at time since they\n      ## may mask each other\n      if(any(aod$Df == 0, na.rm=TRUE)) {\n        zdf <- aod$Df == 0 & !is.na(aod$Df)\n        change <- rev(rownames(aod)[zdf])[1L]\n      }\n    }\n    if(is.null(change)) {\n      if(forward && length(scope$add)) {\n        aodf <- add1(\n          fit, scope$add, scale = scale,\n          k = k, trace = trace >= 1, fixed = fixed.add1.drop1,\n          use.fitted.param = use.fitted.param, verbose = verbose,\n          ncores = ncores, data = data, ...\n        )\n        rn <- row.names(aodf)\n        row.names(aodf) <- c(rn[1L], paste(\"+\", rn[-1L], sep=\" \"))\n        aod <-\n        if(is.null(aod)) aodf\n        else rbind(aod, aodf[-1L, , drop = FALSE])\n      }\n      attr(aod, \"heading\") <- NULL\n      ## need to remove any terms with zero df from consideration\n      nzdf <- if(!is.null(aod$Df))\n      aod$Df != 0 | is.na(aod$Df)\n      aod <- aod[nzdf, ]\n      if(is.null(aod) || NCOL(aod) == 0L) break\n      nc <- match(c(\"Cp\", \"AIC\"), names(aod))\n      nc <- nc[!is.na(nc)][1L]\n      o <- order(aod[, nc])\n      if(trace) print(aod[o, ])\n      if(o[1L] == 1) break\n      change <- rownames(aod)[o[1L]]\n    }\n    usingCp <- match(\"Cp\", names(aod), 0L) > 0L\n    ## may need to look for a `data' argument in parent\n    ## was:\n    ##     fit <- update(fit, paste(\"~ .\", change), evaluate = FALSE)\n    ##     fit <- eval.parent(fit)\n\n    #     nfit <- switch(\n    #       substr( change, 1, 1 ),\n    #       \"-\" = attr( aod, \"nfit\" ),\n    #       \"+\" = attr( aodf, \"nfit\" )\n    #     )\n\n    fit <- update(\n      fit, paste(\"~ .\", change), verbose = verbose, object. = fit\n    )\n\n    cl <- object[[\"call\"]]\n    cl[\"formula\"] <- fit[[\"call\"]][\"formula\"]\n    fit[[\"call\"]] <- cl\n\n    nnew <- nobs(fit, use.fallback = TRUE)\n    if(all(is.finite(c(n, nnew))) && nnew != n)\n    stop(\"number of rows in use has changed: remove missing values?\")\n    Terms <- terms(fit)\n    bAIC <- extractAIC(fit, scale, k = k, REML = FALSE, ...)\n    edf <- bAIC[1L]\n    bAIC <- bAIC[2L]\n    if( fixed.add1.drop1 && !fixed.step ) bAIC <- bAIC - k * n.fitted.param.aniso\n    if(trace) {\n      cat(\"\\nStep:  AIC=\", format(round(bAIC, 2)), \"\\n\",\n        cut.string(deparse(formula(fit))), \"\\n\\n\", sep = \"\")\n      utils::flush.console()\n    }\n    ## add a tolerance as dropping 0-df terms might increase AIC slightly\n    if(bAIC >= AIC + 1.e-7) break\n#     nm <- nm + 1L\n    ## FIXME: think about using df.residual() here.\n    models[[nm]] <-\n    list(deviance = mydeviance(fit, ...), df.resid = n - edf,\n      change = change, AIC = bAIC)\n    if(!is.null(keep)) keep.list[[nm]] <- keep(fit, bAIC)\n  }\n  if(!is.null(keep)) fit$keep <- re.arrange(keep.list[seq(nm)])\n  step.results(models = models[seq(nm)], fit, object, usingCp)\n}"

